1	package com.maritime.platform.gateway.security;
2	
3	import java.util.ArrayList;
4	import java.util.Collections;
5	import java.util.HashSet;
6	import java.util.List;
7	import java.util.Locale;
8	import java.util.Set;
9	
10	import org.springframework.beans.factory.InitializingBean;
11	import org.springframework.http.server.reactive.ServerHttpRequest;
12	import org.springframework.stereotype.Component;
13	import org.springframework.web.util.pattern.PathPattern;
14	import org.springframework.web.util.pattern.PathPatternParser;
15	import org.springframework.web.util.pattern.PatternParseException;
16	
17	@Component
18	public class RouteSecurityPolicyResolver implements InitializingBean {
19	
20		private final GatewaySecurityProperties properties;
21	
22		private final List<GatewaySecurityPolicyCustomizer> customizers;
23	
24		private final List<String> programmaticPublicPaths = new ArrayList<>();
25	
26		private final List<ProgrammaticRouteRule> programmaticRoutes = new ArrayList<>();
27	
28		private List<CompiledPublicPath> compiledPublicPaths = Collections.emptyList();
29	
30		private List<CompiledRouteRule> compiledRoutes = Collections.emptyList();
31	
32		private AuthMode defaultAuthMode;
33	
34		private volatile boolean initialized;
35	
36		public RouteSecurityPolicyResolver(GatewaySecurityProperties properties) {
37			this(properties, Collections.emptyList());
38		}
39	
40		public RouteSecurityPolicyResolver(GatewaySecurityProperties properties,
41		                                   List<GatewaySecurityPolicyCustomizer> customizers) {
42			this.properties = properties;
43			this.customizers = customizers != null ? customizers : Collections.emptyList();
44		}
45	
46		// ---------- programmatic registration (for customizers) ----------
47	
48		public void addPublicPath(String publicPath) {
49			checkNotInitialized();
50			programmaticPublicPaths.add(publicPath);
51		}
52	
53		public void addRoutePolicy(String id, List<String> paths, List<String> methods, AuthMode authMode) {
54			checkNotInitialized();
55			if (authMode == AuthMode.JWT_AND_HMAC) {
56				throw new IllegalArgumentException(
57						"Route '" + id + "' uses JWT_AND_HMAC which is reserved and not yet implemented");
58			}
59			programmaticRoutes.add(new ProgrammaticRouteRule(id, paths, methods, authMode));
60		}
61	
62		// ---------- resolution ----------
63	
64		public RouteSecurityPolicy resolve(ServerHttpRequest request) {
65			return resolve(request.getURI().getPath(), request.getMethod() != null ? request.getMethod().name() : null);
66		}
67	
68		public RouteSecurityPolicy resolve(String path, String httpMethod) {
69			if (!initialized) {
70				compile();
71			}
72			// 1. Public paths take absolute priority — always NONE
73			for (CompiledPublicPath cpp : compiledPublicPaths) {
74				if (cpp.pattern.matches(PathContainerAdapter.parse(path))) {
75					return new RouteSecurityPolicy(AuthMode.NONE, cpp.ruleId);
76				}
77			}
78			// 2. Route policies
79			for (CompiledRouteRule crr : compiledRoutes) {
80				if (crr.matches(path, httpMethod)) {
81					return new RouteSecurityPolicy(crr.authMode, crr.ruleId);
82				}
83			}
84			// 3. Default
85			return new RouteSecurityPolicy(defaultAuthMode, "DEFAULT");
86		}
87	
88		public AuthMode getDefaultAuthMode() {
89			return defaultAuthMode;
90		}
91	
92		// ---------- initialization ----------
93	
94		@Override
95		public void afterPropertiesSet() {
96			compile();
97		}
98	
99		private void compile() {
100			if (initialized) {
101				return;
102			}
103			PathPatternParser parser = new PathPatternParser();
104			parser.setMatchOptionalTrailingSeparator(true);
105	
106			List<CompiledPublicPath> publicPatterns = new ArrayList<>();
107			List<CompiledRouteRule> routeRules = new ArrayList<>();
108	
109			// Apply customizers to collect programmatic registrations
110			for (GatewaySecurityPolicyCustomizer customizer : customizers) {
111				customizer.customize(this);
112			}
113	
114			// Compile public paths from properties
115			for (String path : properties.getPublicPaths()) {
116				publicPatterns.add(new CompiledPublicPath(compilePattern(parser, path), "PUBLIC:" + path));
117			}
118			// Compile programmatic public paths
119			for (String path : programmaticPublicPaths) {
120				publicPatterns.add(new CompiledPublicPath(compilePattern(parser, path), "PUBLIC(custom):" + path));
121			}
122	
123			// Compile route policies from properties
124			for (GatewaySecurityProperties.RoutePolicy rp : properties.getRoutes()) {
125				Set<String> methods = uppercaseSet(rp.getMethods());
126				for (String path : rp.getPaths()) {
127					routeRules.add(new CompiledRouteRule(
128							compilePattern(parser, path), rp.getId(), methods, rp.getAuthMode()));
129				}
130			}
131			// Compile programmatic route policies
132			for (ProgrammaticRouteRule pr : programmaticRoutes) {
133				Set<String> methods = uppercaseSet(pr.methods);
134				for (String path : pr.paths) {
135					routeRules.add(new CompiledRouteRule(
136							compilePattern(parser, path), pr.id, methods, pr.authMode));
137				}
138			}
139	
140			this.compiledPublicPaths = Collections.unmodifiableList(publicPatterns);
141			this.compiledRoutes = Collections.unmodifiableList(routeRules);
142			this.defaultAuthMode = properties.getDefaultAuthMode();
143			this.initialized = true;
144		}
145	
146		private static PathPattern compilePattern(PathPatternParser parser, String pattern) {
147			try {
148				return parser.parse(pattern);
149			} catch (PatternParseException e) {
150				throw new IllegalStateException("Invalid path pattern '" + pattern + "': " + e.getMessage(), e);
151			}
152		}
153	
154		private static Set<String> uppercaseSet(List<String> values) {
155			if (values == null || values.isEmpty()) {
156				return Collections.emptySet();
157			}
158			Set<String> set = new HashSet<>(values.size());
159			for (String v : values) {
160				if (v != null && !v.isBlank()) {
161					set.add(v.strip().toUpperCase(Locale.ROOT));
162				}
163			}
164			return Collections.unmodifiableSet(set);
165		}
166	
167		private void checkNotInitialized() {
168			if (initialized) {
169				throw new IllegalStateException(
170						"RouteSecurityPolicyResolver is already initialized. " +
171						"addPublicPath / addRoutePolicy must be called from a GatewaySecurityPolicyCustomizer.");
172			}
173		}
174	
175		// ---------- internal types ----------
176	
177		private static class CompiledPublicPath {
178			final PathPattern pattern;
179			final String ruleId;
180	
181			CompiledPublicPath(PathPattern pattern, String ruleId) {
182				this.pattern = pattern;
183				this.ruleId = ruleId;
184			}
185		}
186	
187		private static class CompiledRouteRule {
188			final PathPattern pattern;
189			final String ruleId;
190			final Set<String> methods;
191			final AuthMode authMode;
192	
193			CompiledRouteRule(PathPattern pattern, String ruleId, Set<String> methods, AuthMode authMode) {
194				this.pattern = pattern;
195				this.ruleId = ruleId;
196				this.methods = methods;
197				this.authMode = authMode;
198			}
199	
200			boolean matches(String path, String httpMethod) {
201				if (!this.pattern.matches(PathContainerAdapter.parse(path))) {
202					return false;
203				}
204				if (methods.isEmpty()) {
205					return true;
206				}
207				if (httpMethod == null) {
208					return false;
209				}
210				return methods.contains(httpMethod.toUpperCase(Locale.ROOT));
211			}
212		}
213	
214		private static class ProgrammaticRouteRule {
215			final String id;
216			final List<String> paths;
217			final List<String> methods;
218			final AuthMode authMode;
219	
220			ProgrammaticRouteRule(String id, List<String> paths, List<String> methods, AuthMode authMode) {
221				this.id = id;
222				this.paths = paths != null ? paths : Collections.emptyList();
223				this.methods = methods != null ? methods : Collections.emptyList();
224				this.authMode = authMode;
225			}
226		}
227	
228		/**
229		/**
230		 * Adapter that bridges a string path to {@link org.springframework.http.server.PathContainer}
231		 * without requiring the spring-web dependency at the API level.
232		 */
233		private static final class PathContainerAdapter {
234			private PathContainerAdapter() {}
235	
236			static org.springframework.http.server.PathContainer parse(String path) {
237				return org.springframework.http.server.PathContainer.parsePath(path);
238			}
239		}
240	}
