78			String signature = exchange.getRequest().getHeaders().getFirst(hdrs.getSignature());
79	
80			if (isAnyBlank(appKey, timestamp, nonce, bodyDigest, signature)) {
81				return errorWriter.write(exchange, GatewayAuthErrorCode.MISSING_HMAC_HEADERS);
82			}
83	
84			return readAndCacheBody(exchange)
85					.flatMap(cachedExchange -> {
86						byte[] bodyBytes = cachedExchange.getAttribute("gateway.cachedBody");
87						String method = exchange.getRequest().getMethod().name();
88						String rawPath = exchange.getRequest().getURI().getRawPath();
89						String rawQuery = exchange.getRequest().getURI().getRawQuery();
90	
91						return authManager.authenticate(appKey, timestamp, nonce, bodyDigest, signature,
92										method, rawPath, rawQuery, bodyBytes != null ? bodyBytes : new byte[0])
93								.flatMap(principal -> {
94									cachedExchange.getAttributes().put(GatewayPrincipal.ATTRIBUTE, principal);
95									return chain.filter(cachedExchange);
96								})
97								.onErrorResume(JwtAuthenticationException.class,
98										e -> errorWriter.write(cachedExchange, e.getErrorCode()));
99					});
100		}
101	
102		@Override
103		public int getOrder() {
104			return GatewayFilterOrder.HMAC_AUTHENTICATION;
105		}
106	
107		/**
108		 * Reads the request body once, caches the bytes, and returns a decorated exchange
109		 * whose request body can be re-read by downstream filters and handlers.
110		 */
111		private Mono<ServerWebExchange> readAndCacheBody(ServerWebExchange exchange) {
112			return DataBufferUtils.join(exchange.getRequest().getBody())
113					.map(buf -> {
114						byte[] bytes = new byte[buf.readableByteCount()];
115						buf.read(bytes);
116						DataBufferUtils.release(buf);
117						return bytes;
118					})
119					.switchIfEmpty(Mono.just(new byte[0]))
120					.map(bytes -> {
121						ServerHttpRequest decorated = new ServerHttpRequestDecorator(exchange.getRequest()) {
122							@Override
123							public Flux<DataBuffer> getBody() {
124								return Flux.just(
125										exchange.getResponse().bufferFactory().wrap(bytes));
126							}
127						};
128						ServerWebExchange cached = exchange.mutate().request(decorated).build();
129						cached.getAttributes().put("gateway.cachedBody", bytes);
130						return cached;
131					});
132		}
133	
134		private boolean hasBearerToken(ServerWebExchange exchange) {
135			String auth = exchange.getRequest().getHeaders().getFirst("Authorization");
136			return auth != null && auth.startsWith("Bearer ");
137		}
138	
139		private boolean isAnyBlank(String... values) {
140			for (String v : values) {
141				if (v == null || v.isBlank()) {
142					return true;
143				}
144			}
145			return false;
146		}
147	
148	}
