42			this(properties, claimsMapper, Clock.systemUTC(), null);
43		}
44	
45		public JwtAuthenticationManager(GatewaySecurityProperties properties, JwtClaimsMapper claimsMapper,
46				JwtStateValidator stateValidator) {
47			this(properties, claimsMapper, Clock.systemUTC(), stateValidator);
48		}
49	
50		JwtAuthenticationManager(GatewaySecurityProperties properties, JwtClaimsMapper claimsMapper, Clock clock) {
51			this(properties, claimsMapper, clock, null);
52		}
53	
54		JwtAuthenticationManager(GatewaySecurityProperties properties, JwtClaimsMapper claimsMapper, Clock clock,
55				JwtStateValidator stateValidator) {
56			this.jwtConfig = properties.getJwt();
57			this.signingKey = Keys.hmacShaKeyFor(jwtConfig.getSecret().getBytes(StandardCharsets.UTF_8));
58			this.encryptor = jwtConfig.isEncrypted() ? new JwtEncryptor(jwtConfig.getSecret()) : null;
59			this.claimsMapper = claimsMapper;
60			this.clock = clock;
61			this.stateValidator = stateValidator;
62		}
63	
64		/**
65		 * Authenticate the given token string, returning a mapped user principal
66		 * or an error signal carrying a {@link JwtAuthenticationException}.
67		 */
68		public Mono<GatewayPrincipal.User> authenticate(String token) {
69			return Mono.fromCallable(() -> doParseAndMap(token))
70					.flatMap(result -> {
71						if (stateValidator == null) {
72							return Mono.just(result.user);
73						}
74						return stateValidator.validate(result.user.sessionId(), result.jti, result.user.userId())
75								.thenReturn(result.user);
76					});
77		}
78	
79		private AuthResult doParseAndMap(String token) {
80			String rawToken = decryptIfNeeded(token);
81			Claims claims = parseAndValidate(rawToken);
82			GatewayPrincipal.User user = claimsMapper.map(claims);
83			validateRequiredClaims(user);
84			String jti = claims.getId();
85			return new AuthResult(user, jti);
86		}
87	
88		private String decryptIfNeeded(String token) {
89			if (encryptor == null) {
90				return token;
91			}
92			String decrypted = encryptor.decrypt(token);
93			if (decrypted == null) {
94				throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN,
95						"Token decryption failed");
96			}
97			return decrypted;
98		}
99	
100		private Claims parseAndValidate(String token) {
101			try {
102				Jws<Claims> jws = Jwts.parser()
103						.verifyWith(signingKey)
104						.clockSkewSeconds(jwtConfig.getClockSkewSeconds())
105						.clock(() -> Date.from(clock.instant()))
106						.build()
107						.parseSignedClaims(token);
108	
109				Claims claims = jws.getPayload();
110	
111				String issuer = claims.getIssuer();
112				if (!jwtConfig.getIssuer().equals(issuer)) {
113					throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN,
114							"Invalid issuer: " + issuer);
115				}
116	
117				Date expiration = claims.getExpiration();
118				if (expiration != null) {
119					Instant expiryInstant = expiration.toInstant();
120					Instant threshold = clock.instant().minusSeconds(jwtConfig.getClockSkewSeconds());
121					if (expiryInstant.isBefore(threshold)) {
122						throw new JwtAuthenticationException(GatewayAuthErrorCode.TOKEN_EXPIRED,
123								"Token expired at " + expiration);
124					}
125				}
126	
127				return claims;
128			} catch (ExpiredJwtException e) {
129				throw new JwtAuthenticationException(GatewayAuthErrorCode.TOKEN_EXPIRED, e.getMessage());
130			} catch (JwtAuthenticationException e) {
131				throw e;
132			} catch (Exception e) {
133				throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN, e.getMessage());
134			}
135		}
136	
137		private void validateRequiredClaims(GatewayPrincipal.User user) {
138			if (!StringUtils.hasText(user.userId())) {
139				throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN,
140						"Required claim '" + jwtConfig.getClaims().getUserId() + "' is missing or empty");
141			}
142			if (!StringUtils.hasText(user.sessionId())) {
143				throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN,
144						"Required claim '" + jwtConfig.getClaims().getSessionId() + "' is missing or empty");
145			}
146		}
147	
148		/**
149		 * Intermediate result holding the mapped user and the JWT ID for
150		 * downstream state validation.
151		 */
152		private static class AuthResult {
153			final GatewayPrincipal.User user;
154			final String jti;
155	
156			AuthResult(GatewayPrincipal.User user, String jti) {
157				this.user = user;
158				this.jti = jti;
159			}
160		}
161	}
