2	
3	import com.maritime.platform.gateway.security.GatewayPrincipal;
4	import com.maritime.platform.gateway.security.GatewaySecurityProperties;
5	import com.maritime.platform.gateway.security.jwt.GatewayAuthErrorCode;
6	import com.maritime.platform.gateway.security.jwt.JwtAuthenticationException;
7	
8	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
9	import org.springframework.stereotype.Component;
10	
11	import reactor.core.publisher.Mono;
12	
13	import javax.crypto.Mac;
14	import javax.crypto.spec.SecretKeySpec;
15	import java.nio.charset.StandardCharsets;
16	import java.security.MessageDigest;
17	import java.time.Clock;
18	import java.time.Duration;
19	import java.util.HexFormat;
20	
21	/**
22	 * Authenticates system-to-system requests using HMAC-SHA256 signatures.
23	 *
24	 * <p>Validation sequence:
25	 * <ol>
26	 *   <li>Validate timestamp is within the configured tolerance window</li>
27	 *   <li>Validate nonce length meets the configured minimum</li>
28	 *   <li>Compute SHA-256 of the request body and compare with client digest (constant-time)</li>
29	 *   <li>Check nonce has not been replayed via Redis SETNX</li>
30	 *   <li>Resolve the app credential via {@link AppCredentialResolver}</li>
31	 *   <li>Build the canonical request string and compute HMAC-SHA256</li>
32	 *   <li>Compare computed signature with client signature (constant-time)</li>
33	 * </ol>
34	 */
35	@Component
36	@ConditionalOnProperty("maritime.gateway.security.hmac.enabled")
37	public class HmacAuthenticationManager {
38	
39		private static final String HMAC_ALGORITHM = "HmacSHA256";
40		private static final HexFormat HEX = HexFormat.of();
41	
42		private final GatewaySecurityProperties properties;
43		private final HmacCanonicalRequestBuilder canonicalBuilder;
44		private final HmacNonceValidator nonceValidator;
45		private final AppCredentialResolver credentialResolver;
46		private final Clock clock;
47	
48		public HmacAuthenticationManager(GatewaySecurityProperties properties,
49				HmacCanonicalRequestBuilder canonicalBuilder,
50				HmacNonceValidator nonceValidator,
51				AppCredentialResolver credentialResolver) {
52			this(properties, canonicalBuilder, nonceValidator, credentialResolver, Clock.systemUTC());
53		}
54	
55		public HmacAuthenticationManager(GatewaySecurityProperties properties,
56				HmacCanonicalRequestBuilder canonicalBuilder,
57				HmacNonceValidator nonceValidator,
58				AppCredentialResolver credentialResolver, Clock clock) {
59			this.properties = properties;
60			this.canonicalBuilder = canonicalBuilder;
61			this.nonceValidator = nonceValidator;
62			this.credentialResolver = credentialResolver;
63			this.clock = clock;
64		}
65	
66		/**
67		 * Authenticates an HMAC-signed request.
68		 *
69		 * @param appKey       the app key from X-App-Key header
70		 * @param timestamp    epoch millis from X-Timestamp header
71		 * @param nonce        nonce from X-Nonce header
72		 * @param clientDigest SHA-256 hex of the request body from X-Body-Digest header
73		 * @param clientSig    HMAC-SHA256 hex signature from X-Signature header
74		 * @param method       uppercase HTTP method
75		 * @param rawPath      raw URI path
76		 * @param rawQuery     raw URI query string
77		 * @param bodyBytes    the request body bytes (empty array for no body)
78		 * @return Mono of App principal on success
79		 */
80		public Mono<GatewayPrincipal.App> authenticate(String appKey, String timestamp,
81				String nonce, String clientDigest, String clientSig,
82				String method, String rawPath, String rawQuery, byte[] bodyBytes) {
83	
84			GatewaySecurityProperties.Hmac hmac = properties.getHmac();
85			Duration tolerance = hmac.getTimestampTolerance();
86			int minNonceLength = hmac.getMinNonceLength();
87	
88			// 1. Validate timestamp window
89			long ts;
90			try {
91				ts = Long.parseLong(timestamp);
92			} catch (NumberFormatException e) {
93				return Mono.error(new JwtAuthenticationException(
94						GatewayAuthErrorCode.TIMESTAMP_EXPIRED,
95						"Invalid timestamp format: " + timestamp));
96			}
97			long now = clock.millis();
98			if (Math.abs(now - ts) > tolerance.toMillis()) {
99				return Mono.error(new JwtAuthenticationException(
100						GatewayAuthErrorCode.TIMESTAMP_EXPIRED,
101						"Timestamp is outside the allowed tolerance window"));
102			}
103	
104			// 2. Validate nonce length
105			if (nonce == null || nonce.length() < minNonceLength) {
106				return Mono.error(new JwtAuthenticationException(
107						GatewayAuthErrorCode.INVALID_SIGNATURE,
108						"Nonce is too short, minimum length is " + minNonceLength));
109			}
110	
111			// 3. Compute body digest and compare
112			String computedDigest = sha256Hex(bodyBytes);
113			if (!constantTimeEquals(computedDigest, clientDigest)) {
114				return Mono.error(new JwtAuthenticationException(
115						GatewayAuthErrorCode.INVALID_SIGNATURE,
116						"Body digest does not match"));
117			}
118	
119			// 4. Validate nonce (Redis SETNX), then resolve credential
120			return nonceValidator.validate(appKey, nonce)
121					.then(Mono.defer(() -> credentialResolver.resolve(appKey)))
122					.flatMap(credential -> {
123						// 5. Build canonical string and compute signature
124						String canonical = canonicalBuilder.build(appKey, method, rawPath,
125								rawQuery, timestamp, nonce, clientDigest);
126	
127						String computedSig = hmacSha256Hex(credential.getAppSecret(), canonical);
128						if (!constantTimeEquals(computedSig, clientSig)) {
129							return Mono.error(new JwtAuthenticationException(
130									GatewayAuthErrorCode.INVALID_SIGNATURE,
131									"Signature does not match"));
132						}
133	
134						String appCode = credential.getAppCode() != null ? credential.getAppCode() : appKey;
135						return Mono.just(new GatewayPrincipal.App(
136								appKey, appCode,
137								credential.getAppId(),
138								credential.getTenantId(),
139								credential.getTenantCode(),
140								credential.getPermissions()));
141					});
142		}
143	
144		static String sha256Hex(byte[] data) {
145			try {
146				return HEX.formatHex(MessageDigest.getInstance("SHA-256").digest(data));
147			} catch (java.security.NoSuchAlgorithmException e) {
148				throw new RuntimeException("SHA-256 algorithm not available", e);
149			}
150		}
151	
152		static String hmacSha256Hex(String key, String data) {
153			try {
154				Mac mac = Mac.getInstance(HMAC_ALGORITHM);
155				SecretKeySpec spec = new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8), HMAC_ALGORITHM);
156				mac.init(spec);
157				return HEX.formatHex(mac.doFinal(data.getBytes(StandardCharsets.UTF_8)));
158			} catch (java.security.NoSuchAlgorithmException | java.security.InvalidKeyException e) {
159				throw new RuntimeException("HMAC-SHA256 algorithm not available", e);
160			}
161		}
162	
163		static boolean constantTimeEquals(String a, String b) {
164			if (a == null || b == null) {
165				return a == b;
166			}
167			return MessageDigest.isEqual(
168					a.getBytes(StandardCharsets.UTF_8),
169					b.getBytes(StandardCharsets.UTF_8));
170		}
171	}
